module.exports = "/* DESIGN SYSTEM OFFICIAL GN IPTV CLIENTES (Royal Blue & Gold Accent) */\n\n:root {\n  --bg-ice-blue: #f0f5fc;      /* Fundo Azul Gelo Nítido */\n  --bg-card: #ffffff;\n  --bg-subtle: #e2edf8;\n  --border-color: #cbd5e1;\n  --color-primary: #0d55bc;   /* Royal Blue Oficial GN */\n  --color-primary-hover: #0a469e;\n  --color-gold: #ffb703;      /* Amarelo Ouro Oficial GN */\n  --text-main: #000000;\n  --text-muted: #000000;\n}\n\nbody {\n  background-color: #f0f5fc !important; /* Fundo Azul Clarinho com Alta Visibilidade */\n  color: #000000 !important;\n  font-size: 16px;\n  line-height: 1.6;\n  padding-bottom: 75px; /* Espaço para menu inferior no celular */\n}\n\n/* Regra Geral de Alta Visibilidade: Texto em Preto Nítido e Forte */\np, span:not(.text-white):not(.badge-text-white), h1, h2, h3, h4, h5, h6, label, td, th {\n  color: #000000 !important;\n}\n\nlabel, h1, h2, h3, th {\n  font-weight: 800 !important;\n}\n\n@media (min-width: 768px) {\n  body {\n    padding-bottom: 0px;\n  }\n}\n\n/* Tamanho de Fonte Geral Aumentado */\ninput, select, textarea, button {\n  font-size: 15px !important;\n  font-weight: 700 !important;\n}\n\nh1 { font-size: 24px !important; }\nh2 { font-size: 20px !important; }\nh3 { font-size: 18px !important; }\n\n/* Navegação por Abas */\n.nav-tab {\n  color: #000000 !important;\n  background-color: #ffffff;\n  border: 1.5px solid #cbd5e1;\n  font-weight: 800;\n  font-size: 15px !important;\n  white-space: nowrap;\n  border-radius: 1rem;\n  transition: all 0.2s ease;\n}\n\n.nav-tab:hover {\n  color: #0d55bc !important;\n  background-color: #e2edf8;\n}\n\n.nav-tab.active {\n  color: #ffffff !important;\n  background-color: #0d55bc !important;\n  border-color: #ffb703 !important;\n  box-shadow: 0 4px 14px 0 rgba(13, 85, 188, 0.35);\n}\n\n/* CARDS DE CLIENTES COM CORES DE FUNDO PERSONALIZADAS E DESIGN DE IMPACTO */\n.client-card {\n  border-radius: 1.5rem;\n  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);\n  border-width: 2px;\n  position: relative;\n  overflow: hidden;\n  box-shadow: 0 4px 12px rgba(13, 85, 188, 0.06);\n}\n\n.client-card:hover {\n  transform: translateY(-4px);\n  box-shadow: 0 16px 28px -6px rgba(13, 85, 188, 0.2);\n}\n\n/* Status: Ativo (Verde Suave) */\n.client-card.status-active {\n  background-color: #f0fdf4 !important;\n  border-color: #86efac !important;\n}\n\n/* Status: Vencendo (Amarelo Suave) */\n.client-card.status-expiring {\n  background-color: #fffbeb !important;\n  border-color: #fde047 !important;\n}\n\n/* Status: Vencido (Vermelho Suave) */\n.client-card.status-expired {\n  background-color: #fef2f2 !important;\n  border-color: #fca5a5 !important;\n}\n\n/* Inputs e Formulários Claros */\ninput[type=\"text\"], input[type=\"password\"], input[type=\"date\"], input[type=\"number\"], select, textarea {\n  background-color: #ffffff !important;\n  color: #000000 !important;\n  border-color: #cbd5e1 !important;\n  font-weight: 700 !important;\n}\n\ninput[type=\"text\"]:focus, input[type=\"password\"]:focus, select:focus, textarea:focus {\n  border-color: #0d55bc !important;\n  ring: 2px #0d55bc !important;\n}\n\n/* Custom Scrollbar */\n::-webkit-scrollbar {\n  width: 6px;\n  height: 6px;\n}\n\n::-webkit-scrollbar-track {\n  background: #e2edf8;\n}\n\n::-webkit-scrollbar-thumb {\n  background: #0d55bc;\n  border-radius: 4px;\n}\n\n/* Barra de Navegação Inferior para Celulares (Bottom Nav Bar) */\n.mobile-bottom-nav {\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  background: rgba(255, 255, 255, 0.98);\n  backdrop-filter: blur(12px);\n  border-top: 2px solid #cbd5e1;\n  z-index: 45;\n  display: flex;\n  justify-content: space-around;\n  align-items: center;\n  padding: 8px 4px;\n  box-shadow: 0 -4px 20px rgba(13, 85, 188, 0.12);\n}\n\n.mobile-bottom-btn {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  color: #000000 !important;\n  font-size: 12px;\n  font-weight: 800;\n  padding: 6px 12px;\n  border-radius: 14px;\n  transition: all 0.2s ease;\n}\n\n.mobile-bottom-btn.active {\n  color: #ffffff !important;\n  background-color: #0d55bc !important;\n}\n";